const input=document.getElementById("text-input"),output=document.getElementById("text-output");function encodeBase64(){try{const t=input.value;if(!t)return output.textContent=i18n.t("common.enter_text");output.textContent=utf8ToBase64(t),output.style.color="var(--text)"}catch(t){output.textContent="\u274C \uC778\uCF54\uB529 \uC624\uB958: "+t.message,output.style.color="#ef4444"}}function decodeBase64(){try{const t=input.value.trim();if(!t)return output.textContent=i18n.t("common.enter_base64");output.textContent=base64ToUtf8(t),output.style.color="var(--text)"}catch{output.textContent=i18n.t("common.error_decoding"),output.style.color="#ef4444"}}function copyResult(){copyToClipboard(output.textContent).then(()=>showToast(i18n.t("common.copied")))}function downloadResult(){const t=output.textContent;if(!t||t===i18n.t("common.result_placeholder")||t.startsWith("\u274C"))return showToast(i18n.t("common.no_result"));downloadFile(t,"base64-result.txt")}function clearAll(){input.value="",output.textContent=i18n.t("common.result_placeholder"),output.style.color="var(--text-muted)"}
